import React, { cloneElement } from 'react';
import { ProgressTrackerContentProps } from './ProgressTrackerContent.types';

const ProgressTrackerContent = ({ children }: ProgressTrackerContentProps): JSX.Element => {
  const stepContentItems = React.Children.map(
    children as React.ReactElement[],
    (child: React.ReactElement, index: number) =>
      cloneElement(child, {
        index,
        ...child.props,
      })
  );
  return <div>{stepContentItems}</div>;
};

export default ProgressTrackerContent;
